using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System.Text.Json;
using TaiChuWeb_V2.DbContext;

namespace TaiChuWeb_V2.Controllers.knowledgeBase;

public sealed class CatalogItem
{
    public string Id { get; set; } = "";
    public string Type { get; set; } = "";
    public string Title { get; set; } = "";
    public string Summary { get; set; } = "";
    public string Author { get; set; } = "";
    public string Tags { get; set; } = "";
    public string? CoverUrl { get; set; }
    public DateTime UpdatedAt { get; set; }
}

// 仅聚合公开来源，不建立副本或另一套发布状态。
[ApiController]
[Route("api/knowledge-base/catalog")]
public class CatalogController(AppDbContext db) : ControllerBase
{
    public static IQueryable<CatalogItem> Query(AppDbContext db, string type)
    {
        var sources = new Dictionary<string, IQueryable<CatalogItem>>
        {
            ["blog"] = db.PublishedNotes.Where(n => (n.Type == "blog" || n.Type == "note") &&
                (n.OriginalNoteId == null || db.Notes.Any(s => s.Id.ToString() == EF.Functions.Collate(n.OriginalNoteId.ToString(), "utf8mb4_general_ci") && s.IsPublic && s.Status != 2)))
                .Select(n => new CatalogItem { Id = n.Id.ToString(), Type = "blog", Title = n.Title ?? "无标题文章", Summary = n.Excerpt ?? "",
                    Author = n.AuthorName ?? "", Tags = n.Tags ?? "", CoverUrl = null, UpdatedAt = n.PublishedAt }),
            ["post"] = db.PublishedNotes.Where(n => n.Type == "post" &&
                (n.OriginalNoteId == null || db.Notes.Any(s => s.Id.ToString() == EF.Functions.Collate(n.OriginalNoteId.ToString(), "utf8mb4_general_ci") && s.IsPublic && s.Status != 2)))
                .Select(n => new CatalogItem { Id = n.Id.ToString(), Type = "post", Title = n.Title ?? "短帖", Summary = n.Excerpt ?? "",
                    Author = n.AuthorName ?? "", Tags = n.Tags ?? "", CoverUrl = null, UpdatedAt = n.PublishedAt }),
            ["artwork"] = db.Artworks.Where(a => a.IsApproved && a.Status == "published")
                .Select(a => new CatalogItem { Id = a.Id.ToString(), Type = "artwork", Title = a.Title, Summary = a.Description ?? "",
                    Author = a.Uploader.Username ?? "", Tags = "", CoverUrl = a.Images.OrderByDescending(i => i.IsCover).ThenBy(i => i.Id).Select(i => i.ImageUrl).FirstOrDefault(), UpdatedAt = a.UploadAt }),
            ["world"] = db.WorldProjects.Where(p => p.IsPublic)
                .Select(p => new CatalogItem { Id = p.Id.ToString(), Type = "world", Title = p.Name, Summary = p.Description ?? "",
                    Author = p.Owner != null ? p.Owner.Username ?? "" : "", Tags = "", CoverUrl = null, UpdatedAt = p.UpdatedAt }),
            ["character"] = db.StickmanCharacters.Where(c => c.Status == "published")
                .Select(c => new CatalogItem { Id = c.Id.ToString(), Type = "character", Title = c.Title, Summary = c.Description ?? "",
                    Author = c.AuthorName, Tags = "", CoverUrl = c.CoverUrl, UpdatedAt = c.UpdatedAt ?? c.CreatedAt }),
            ["wiki"] = db.WikiArticles.Where(a => !a.IsDeleted && a.CurrentRevisionId != null)
                .Select(a => new CatalogItem { Id = a.Id, Type = "wiki", Title = a.Title, Summary = a.Excerpt ?? "", Author = "",
                    Tags = a.Tags ?? "", CoverUrl = null, UpdatedAt = a.UpdatedAt }),
            ["document"] = db.FinalNodes.Where(n => n.Status == 0)
                .Select(n => new CatalogItem { Id = n.Id, Type = "document", Title = n.Title, Summary = n.Excerpt ?? "",
                    Author = n.CreatorName, Tags = n.Tags, CoverUrl = n.CoverImage, UpdatedAt = n.UpdatedAt })
        };
        return type == "all" ? sources.Values.Aggregate((left, right) => left.Concat(right)) : sources[type];
    }

    [HttpGet]
    public async Task<IActionResult> Get([FromQuery] string type = "all", [FromQuery] string? search = null,
        [FromQuery] int page = 1, [FromQuery] int pageSize = 24, [FromQuery] int? categoryId = null)
    {
        if (type is not ("all" or "blog" or "post" or "artwork" or "world" or "character" or "wiki" or "document"))
            return BadRequest(new { message = "不支持的资料类型" });
        if (search?.Length > 100) return BadRequest(new { message = "搜索词不能超过 100 字" });
        pageSize = Math.Clamp(pageSize, 1, 50);
        page = Math.Clamp(page, 1, int.MaxValue / pageSize);
        var query = Query(db, type).AsNoTracking();
        // 保留原百科选择父分类时包含直属子分类的浏览范围。
        if (categoryId.HasValue) query = query.Where(i => i.Type == "wiki" && db.WikiArticles.Any(a => a.Id == i.Id &&
            (a.CategoryId == categoryId || db.WikiCategories.Any(c => c.Id == a.CategoryId && c.ParentId == categoryId))));
        foreach (var term in (search ?? "").Trim().ToLower().Split(' ', StringSplitOptions.RemoveEmptyEntries).Take(10))
        {
            // 旧博客摘要将中文保存为 JSON 的 Unicode 转义，同时兼容原文与转义检索。
            var encoded = JsonSerializer.Serialize(term)[1..^1].ToLowerInvariant();
            query = query.Where(i => i.Title.ToLower().Contains(term) || i.Summary.ToLower().Contains(term) || i.Summary.ToLower().Contains(encoded) || i.Tags.ToLower().Contains(term) || i.Author.ToLower().Contains(term) || (i.Type == "artwork" && db.TagAssignments.Any(t => t.EntityType == "Artwork" && t.EntityId == i.Id && t.Tag != null && t.Tag.Name.ToLower().Contains(term))));
        }
        var total = await query.CountAsync();
        var items = await query.OrderByDescending(i => i.UpdatedAt).ThenBy(i => i.Type).ThenBy(i => i.Id)
            .Skip((page - 1) * pageSize).Take(pageSize).ToListAsync();
        var artworkIds = items.Where(i => i.Type == "artwork").Select(i => i.Id).ToArray();
        var tags = await db.TagAssignments.Where(t => t.EntityType == "Artwork" && Enumerable.Contains(artworkIds, t.EntityId) && t.Tag != null).Select(t => new { t.EntityId, t.Tag!.Name }).ToListAsync();
        foreach (var item in items.Where(i => i.Type == "artwork")) item.Tags = string.Join(",", tags.Where(t => t.EntityId == item.Id).Select(t => t.Name));
        foreach (var item in items.Where(i => i.Type == "blog" && i.Summary.TrimStart().StartsWith('{')))
        {
            try
            {
                using var document = JsonDocument.Parse(item.Summary);
                if (document.RootElement.TryGetProperty("text", out var text) && text.ValueKind == JsonValueKind.String) item.Summary = text.GetString() ?? "";
                if (document.RootElement.TryGetProperty("coverUrl", out var cover) && cover.ValueKind == JsonValueKind.String) item.CoverUrl = cover.GetString();
            }
            catch (JsonException) { /* 历史纯文本保留原值。 */ }
        }
        return Ok(new { items, total, page, pageSize });
    }
}

Controllers/LingMai/LingMaiPublishContro:
// TaiChuWeb_V2/Controllers/LingMai/LingMaiPublishController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System.Text.Json;
using TaiChuWeb_V2.DbContext;
using TaiChuWeb_V2.Dtos.LingMai;
using TaiChuWeb_V2.Models.LingMai;
using TaiChuWeb_V2.Services.Publish; // 引入策略命名空间

namespace TaiChuWeb_V2.Controllers.LingMai
{
    [ApiController]
    [Route("api/[controller]")]
    public class LingMaiPublishController : ControllerBase
    {
        private readonly AppDbContext _context;

        // 🌟 多态分流策略处理器字典
        private readonly Dictionary<string, ILingMaiPublishHandler> _publishHandlers;

        // 获取当前登录用户 ID
        private string? CurrentUserId => User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;

        // 🌟 通过构造函数依赖注入所有的处理器，并自动编排为路由映射字典
        public LingMaiPublishController(AppDbContext context, IEnumerable<ILingMaiPublishHandler> handlers)
        {
            _context = context;
            _publishHandlers = handlers.ToDictionary(h => h.SupportType, h => h);
        }





        [HttpPost("notes/{id:guid}/publish")]
        public async Task<IActionResult> PublishNote([FromRoute] Guid id, [FromBody] PublishRequest req)
        {
            if (!Guid.TryParse(CurrentUserId, out _)) return Unauthorized();

            if (req == null || string.IsNullOrWhiteSpace(req.type)) return BadRequest(new { message = "请选择发布类型" });
            var denied = await CheckOwnerAsync(id, req.type);
            if (denied != null) return denied;

            if (req.type == "note")
            {
                return BadRequest(new { message = "普通随笔碎片属于私密草稿，无法直接发布" });
            }

            // 🌟 纯粹的多态派发：前端发布面板传来什么 type (例如 "doc")，大厅直接交由对应的 Handler 处理
            if (!_publishHandlers.TryGetValue(req.type, out var handler))
            {
                return BadRequest(new { message = $"暂未编织该多态碎片形态 [{req.type}] 的分流大厅逻辑" });
            }

            // 🌟【核心修复点】：补上第四个参数 req.projectId！
            // 只有这样，前端传过来的项目 GUID 才能真正抵达 DocPublishHandler 内部，破除 400 校验拦截！
            return await handler.ExecutePublishAsync(id, CurrentUserId, req.categoryId, req.projectId);
        }

        #region --- 1. 取消发布 ---

        [HttpDelete("notes/{id:guid}/unpublish")]
        public async Task<IActionResult> UnpublishNote(Guid id)
        {
            if (string.IsNullOrEmpty(CurrentUserId)) return Unauthorized();

            var denied = await CheckOwnerAsync(id);
            if (denied != null) return denied;
            var strategy = _context.Database.CreateExecutionStrategy();

            try
            {
                return await strategy.ExecuteAsync<IActionResult>(async () =>
                {
                    var note = await _context.Notes.FindAsync(id);
                    if (note == null) return NotFound(new { message = "未找到草稿" });

                    using var transaction = await _context.Database.BeginTransactionAsync();
                    try
                    {
                        if (note.Type == NoteTypes.Doc)
                        {
                            var noteId = id.ToString();
                            var links = await _context.ProjectDocuments.Where(d => d.NoteId == noteId).ToListAsync();
                            _context.ProjectDocuments.RemoveRange(links);
                            note.UpdatedAt = DateTime.UtcNow;
                            await _context.SaveChangesAsync();
                            await transaction.CommitAsync();
                            return Ok(new { success = true, message = "已取消所有项目分享" });
                        }

                        var existingPublish = await _context.PublishedNotes
                            .FirstOrDefaultAsync(pn => pn.OriginalNoteId == id);

                        if (existingPublish != null)
                        {
                            var pubBlocks = await _context.PublishedBlocks
                                .Where(pb => pb.OwnerId == existingPublish.Id.ToString() && (pb.OwnerType == "note" || pb.OwnerType == existingPublish.Type))
                                .ToListAsync();

                            _context.PublishedBlocks.RemoveRange(pubBlocks);
                            _context.PublishedNotes.Remove(existingPublish);
                        }

                        // Serialize withdrawal with publication through the source note row.
                        await _context.Notes.Where(n => n.Id == id).ExecuteUpdateAsync(s => s.SetProperty(n => n.UpdatedAt, n => n.UpdatedAt));
                        await _context.Artworks.Where(a => a.OriginalNoteId == id).ExecuteUpdateAsync(s => s.SetProperty(a => a.IsApproved, false));
                        note.IsPublic = false;
                        note.UpdatedAt = DateTime.UtcNow;
                        await _context.SaveChangesAsync();
                        await transaction.CommitAsync();

                        return Ok(new { success = true, message = "已取消发布" });
                    }
                    catch (Exception)
                    {
                        await transaction.RollbackAsync();
                        throw;
                    }
                });
            }
            catch (Exception ex)
            {
                return StatusCode(500, new { message = "取消发布异常", error = ex.Message });
            }
        }

        #endregion

        private async Task<IActionResult?> CheckOwnerAsync(Guid id, string? type = null)
        {
            var note = await _context.Notes.AsNoTracking().FirstOrDefaultAsync(n => n.Id == id);
            if (note == null) return NotFound(new { message = "未找到草稿" });
            if (!await _context.Spaces.AnyAsync(s => s.Id == note.SpaceId && s.UserId == CurrentUserId)) return Forbid();
            if (type != null && (note.Type != type || note.Status == 2))
                return BadRequest(new { message = "草稿类型不匹配或已被下架" });
            return null;
        }

        #region --- 2. 广场流与阅读 ---

        [HttpGet("stream")]
        public async Task<IActionResult> GetPublicStream([FromQuery] string? type = "wiki", [FromQuery] string? spaceId = null)
        {
            var query = PublicNotes();

            if (!string.IsNullOrEmpty(type))
            {
                query = query.Where(pn => pn.Type == type);
            }

            var stream = await query
                .OrderByDescending(pn => pn.PublishedAt)
                .Select(pn => new {
                    pn.Id,
                    pn.Title,
                    pn.Type,
                    pn.SpaceId,
                    pn.PublishedAt,
                    pn.Tags,
                    pn.ExtraData,
                    // ✨【性能修复点】：摒弃跨表子查询，直接读取本表已格式化好的摘要字段
                    Excerpt = pn.Excerpt ?? "灵脉深处暂无回响..."
                })
                .ToListAsync();

            return Ok(stream);
        }

        [HttpGet("public-stream")]
        public async Task<IActionResult> GetPublicStream(
            [FromQuery] string? type,
            [FromQuery] int page = 1,
            [FromQuery] int pageSize = 20,
            [FromQuery] string? tag = null)
        {
            var query = PublicNotes();

            if (string.IsNullOrEmpty(type)) //[cite: 1]
            {
                // 🌟 修复：把 "blog" 加上去，让它默认并流展示！
                query = query.Where(pn => pn.Type == "note" || pn.Type == NoteTypes.Post || pn.Type == "blog");
            }
            else //[cite: 1]
            {
                query = query.Where(pn => pn.Type == type); //[cite: 1]
            }

            if (!string.IsNullOrWhiteSpace(tag))
            {
                tag = tag.Trim();
                if (tag.Length > 50) return BadRequest(new { message = "分类标签不能超过 50 字" });
                // 使用发布时的标签快照，兼容 Unicode 转义和未转义的旧 JSON。
                var encoded = JsonSerializer.Serialize(tag);
                var literal = JsonSerializer.Serialize(tag, new JsonSerializerOptions { Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping });
                query = query.Where(pn => pn.Tags != null && (pn.Tags.Contains(encoded) || pn.Tags.Contains(literal) || pn.Tags == tag));
            }

            var safePageSize = Math.Clamp(pageSize, 1, 50);
            page = Math.Clamp(page, 1, int.MaxValue / safePageSize);
            var skipCount = (page - 1) * safePageSize;

            var stream = await query
                .OrderByDescending(pn => pn.PublishedAt)
                .Skip(skipCount)
                .Take(safePageSize)
                .Select(pn => new
                {
                    pn.Id,
                    pn.Title,
                    pn.Type,
                    pn.SpaceId,
                    pn.PublishedAt,
                    pn.Resonance,
                    pn.AuthorName,
                    pn.ExtraData,
                    // ✨【核心兼性能修复点】：直接返回平铺好的本表 Excerpt，不要再去跨表查 PublishedBlocks！
                    Excerpt = pn.Excerpt ?? "灵脉深处暂无回响..."
                })
                .ToListAsync();

            return Ok(stream);
        }

        [HttpGet("published/{id:guid}")]
        public async Task<IActionResult> GetPublishedDetail(Guid id)
        {
            var publishedNote = await PublicNotes().FirstOrDefaultAsync(pn => pn.Id == id);

            if (publishedNote == null)
            {
                return NotFound(new { message = "该词条已进入虚空（未找到）" });
            }

            var blocks = await _context.PublishedBlocks
                .Where(pb => pb.OwnerId == id.ToString())
                .OrderBy(pb => pb.SortOrder)
                .ToListAsync();

            var content = new
            {
                type = "doc",
                content = blocks.Select(b => {
                    try
                    {
                        using var doc = JsonDocument.Parse(b.Data);
                        var root = doc.RootElement;

                        return (object)new
                        {
                            type = b.Type,
                            attrs = root.TryGetProperty("attrs", out var a) ? a.Clone() : (object)new { },
                            content = root.TryGetProperty("content", out var c) ? c.Clone() : (object?)null
                        };
                    }
                    catch
                    {
                        return new { type = "paragraph", content = new[] { new { type = "text", text = "碎片解析异常" } } };
                    }
                }).ToList()
            };

            return Ok(new
            {
                id = publishedNote.Id,
                title = publishedNote.Title,
                authorName = publishedNote.AuthorName,
                publishedAt = publishedNote.PublishedAt,
                tags = publishedNote.Tags,
                content = content
            });
        }

        private IQueryable<PublishedNote> PublicNotes() => _context.PublishedNotes.AsNoTracking().Where(p => p.OriginalNoteId == null || _context.Notes.Any(n => n.Id.ToString() == EF.Functions.Collate(p.OriginalNoteId.ToString(), "utf8mb4_general_ci") && n.IsPublic && n.Status != 2));

        [HttpGet("blog/{id:guid}")]
        public async Task<IActionResult> GetPublicBlog(Guid id)
        {
            var publishedNote = await PublicNotes().FirstOrDefaultAsync(pn => pn.Id == id);

            if (publishedNote == null) return NotFound(new { message = "内容不存在" });

            var canEdit = publishedNote.OriginalNoteId != null && await _context.Notes.AnyAsync(n => n.Id == publishedNote.OriginalNoteId && _context.Spaces.Any(s => s.Id == n.SpaceId && s.UserId == CurrentUserId));
            // 在内存中先转化为标准格式的字符串（全小写），确保 SQL 查询能完美命中
            string ownerIdStr = id.ToString().ToLower();

            var blocksList = await _context.PublishedBlocks
                .AsNoTracking()
                .Where(pb => pb.OwnerId == ownerIdStr)
                .OrderBy(pb => pb.SortOrder)
                .Select(pb => new {
                    id = pb.Id,
                    type = pb.Type,
                    data = pb.Data,
                    sortOrder = pb.SortOrder
                })
                .ToListAsync();

            // 🌟 修复核心：去掉产生冲突的双属性，仅保留单个属性。
            // .NET 默认的 CamelCase 会自动将这里的 "blocks" 在网络传输时转换为小写 "blocks"
            return Ok(new
            {
                id = publishedNote.Id,
                title = publishedNote.Title,
                type = publishedNote.Type,
                publishedAt = publishedNote.PublishedAt,
                authorName = publishedNote.AuthorName, tags = publishedNote.Tags, canEdit, originalNoteId = canEdit ? publishedNote.OriginalNoteId : null,
                blocks = blocksList
            });
        }

        #endregion
    }
}

