﻿using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System.Security.Claims;
using TaiChuWeb_V2.DbContext;
using TaiChuWeb_V2.Models.User;
using TaiChuWeb_V2.Models.Trade;
using System.Reflection;

namespace TaiChuWeb_V2.Controllers
{
    [Authorize]
    [ApiController]
    [Route("api/trade")]
    public class TradeController : ControllerBase
    {
        private readonly AppDbContext _context;

        public TradeController(AppDbContext context) => _context = context;

        /// <summary>
        /// 1. 获取流转中的资源列表 (已合并购买进度)
        /// </summary>
        [HttpGet("items")]
        public async Task<IActionResult> GetActiveItems()
        {
            var userIdStr = GetCurrentUserId();
            if (!Guid.TryParse(userIdStr, out var userId))
            {
                return Ok(await _context.StoreItems.Where(i => i.IsActive).ToListAsync());
            }

            var itemsWithProgress = await _context.StoreItems
                .Where(i => i.IsActive)
                .OrderByDescending(i => i.BaseWeight)
                .Select(item => new {
                    item.Id,
                    item.Name,
                    item.Description,
                    item.Benefit,
                    item.Category,
                    item.BaseCost,
                    item.PriceMultiplier,
                    item.Delivery,
                    item.StaticPayload,
                    // 注入当前用户的购买次数，用于前端计算动态价格
                    PurchaseCount = _context.UserPurchaseProgress
                        .Where(p => p.UserId == userId && p.StoreItemId == item.Id)
                        .Select(p => p.PurchaseCount)
                        .FirstOrDefault()
                })
                .ToListAsync();

            return Ok(itemsWithProgress);
        }

        /// <summary>
        /// 2. 获取当前账户审计状态 (实时查询真实已用配额)
        /// </summary>
        /// <summary>
        /// 2. 获取当前账户审计状态 (实时查询真实已用配额)
        /// </summary>
        [HttpGet("status")]
        public async Task<IActionResult> GetMyStatus()
        {
            var userIdStr = GetCurrentUserId();
            if (!Guid.TryParse(userIdStr, out var userId))
                return Unauthorized(TradeResult.Fail("令牌无效"));

            var user = await _context.Users
                .Include(u => u.Stats)
                .FirstOrDefaultAsync(u => u.Id == userId);

            if (user?.Stats == null) return NotFound(TradeResult.Fail("统计数据丢失"));

            // 🌟 统一逻辑：获取当前用户拥有的所有空间 ID 列表
            var userSpaceIds = await _context.Spaces
                .Where(s => s.UserId == userIdStr)
                .Select(s => s.Id)
                .ToListAsync();

            // 1. 统计空间数：保持原样
            int realUsedSpaces = userSpaceIds.Count;

            // 2. 🌟 核心修复：统计笔记数（与 Quota 接口完全一致）
            int realUsedNotes = await _context.Notes
                .CountAsync(n => userSpaceIds.Contains(n.SpaceId));

            // 3. 统计项目数：保持原样
            int realUsedProjects = await _context.Projects.CountAsync(p => p.OwnerId == userId);

            return Ok(new
            {
                Experience = user.Stats.Experience,
                Level = user.Stats.Level,
                MaxSpaces = user.Stats.MaxSpaces,
                MaxNotes = user.Stats.MaxNotes,
                MaxProjectCount = user.Stats.MaxProjectCount,
                UsedSpaces = realUsedSpaces,
                UsedNotes = realUsedNotes,
                UsedProjectCount = realUsedProjects
            });
        }

        /// <summary>
        /// 3. 执行资源兑换 (通用反射注入版 - 修复重试策略事务报错)
        /// </summary>
        [HttpPost("purchase/{itemId}")]
        public async Task<IActionResult> Purchase(int itemId)
        {
            var userIdStr = GetCurrentUserId();
            if (!Guid.TryParse(userIdStr, out var userId))
                return Unauthorized(TradeResult.Fail("身份核验失败"));

            // 🌟 核心修复：获取当前配置的执行策略 (支持重试机制)
            var strategy = _context.Database.CreateExecutionStrategy();

            // 🌟 将整个事务逻辑包裹在策略的 ExecuteAsync 中
            return await strategy.ExecuteAsync(async () =>
            {
                using var transaction = await _context.Database.BeginTransactionAsync();
                try
                {
                    var item = await _context.StoreItems.Include(i => i.SecretPool).FirstOrDefaultAsync(i => i.Id == itemId);
                    var user = await _context.Users.Include(u => u.Stats).FirstOrDefaultAsync(u => u.Id == userId);

                    if (item == null || user?.Stats == null) return BadRequest(TradeResult.Fail("感应目标不存在"));

                    var progress = await _context.UserPurchaseProgress
                        .FirstOrDefaultAsync(p => p.UserId == userId && p.StoreItemId == itemId)
                        ?? new UserPurchaseProgress { UserId = userId, StoreItemId = itemId, PurchaseCount = 0 };

                    // 🌟 计算当前成本
                    long currentCost = (long)(item.BaseCost * Math.Pow(item.PriceMultiplier, progress.PurchaseCount));

                    if (user.Stats.Experience < currentCost)
                        return BadRequest(TradeResult.Fail($"经验不足，需 {currentCost}"));

                    // --- 核心逻辑执行 ---

                    // A. 扣费与购买次数累加
                    user.Stats.Experience -= currentCost;
                    progress.PurchaseCount++;

                    if (_context.Entry(progress).State == EntityState.Detached)
                        _context.UserPurchaseProgress.Add(progress);

                    // B. 🌟 通用属性注入引擎 (反射)
                    if (!string.IsNullOrWhiteSpace(item.StaticPayload))
                    {
                        var parts = item.StaticPayload.Split(':');
                        if (parts.Length == 2)
                        {
                            string propertyName = parts[0].Trim();
                            if (int.TryParse(parts[1], out int valueToAdd))
                            {
                                // 查找 UserStats 中对应的属性 (忽略大小写)
                                var prop = typeof(UserStats).GetProperty(propertyName,
                                    BindingFlags.Public | BindingFlags.Instance | BindingFlags.IgnoreCase);

                                if (prop != null && prop.CanWrite)
                                {
                                    // 获取当前值并相加
                                    var currentVal = Convert.ToInt32(prop.GetValue(user.Stats));
                                    prop.SetValue(user.Stats, currentVal + valueToAdd);

                                    // 🌟 关键：显式标记该属性已修改，强制 EF 生成 SQL UPDATE 语句
                                    _context.Entry(user.Stats).Property(propertyName).IsModified = true;
                                }
                            }
                        }
                    }

                    // C. 处理密钥/链接交付
                    string deliveryData = "";
                    if (item.Delivery == DeliveryType.SecretKey)
                    {
                        var secret = item.SecretPool?.FirstOrDefault(s => !s.IsUsed);
                        if (secret == null) return BadRequest(TradeResult.Fail("资源已罄"));
                        secret.IsUsed = true;
                        secret.AssignedUserId = userId;
                        secret.AssignedAt = DateTime.Now;
                        deliveryData = secret.SecretCode;
                    }
                    else if (item.Delivery == DeliveryType.Link)
                    {
                        deliveryData = item.StaticPayload ?? "";
                    }

                    await _context.SaveChangesAsync();
                    await transaction.CommitAsync();

                    // 🌟 强行刷新内存，确保返回的是数据库最新状态
                    await _context.Entry(user.Stats).ReloadAsync();

                    return Ok(TradeResult.Success(deliveryData));
                }
                catch (Exception ex)
                {
                    await transaction.RollbackAsync();
                    return StatusCode(500, TradeResult.Fail("灵脉震荡: " + ex.Message));
                }
            });
        }

        private string GetCurrentUserId() => User.FindFirst(ClaimTypes.NameIdentifier)?.Value ?? string.Empty;
    }
}

Controllers/Game/GameController.cs:
﻿using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System.Security.Claims;
using TaiChuWeb_V2.DbContext;
using TaiChuWeb_V2.Dtos.Game;
using TaiChuWeb_V2.Models.Game;
using TaiChuWeb_V2.Models.User;
using TaiChuWeb_V2.Services;

namespace TaiChuWeb_V2.Controllers.Game
{
    [ApiController]
    [Route("api/[controller]")]
    [Authorize]
    public class GamesController : ControllerBase
    {
        private readonly AppDbContext _context;
        private readonly SystemConfigService _configService;

        public GamesController(AppDbContext context, SystemConfigService configService)
        {
            _context = context;
            _configService = configService;
        }

        // ==================== 创建游戏（消耗经验） ====================
        [HttpPost]
        public async Task<IActionResult> CreateGame([FromBody] CreateGameDto dto)
        {
            // 1. 获取当前用户
            var userIdClaim = User.FindFirst(ClaimTypes.NameIdentifier);
            if (userIdClaim == null)
                return Unauthorized("用户未登录");

            var userId = Guid.Parse(userIdClaim.Value);
            var user = await _context.Users
                .Include(u => u.Stats)
                .FirstOrDefaultAsync(u => u.Id == userId);

            if (user == null || user.Stats == null)
                return NotFound("用户不存在");

            // 2. 读取消耗配置
            int cost = await _configService.GetIntAsync("Game:CreateCostExp", 50);

            // 3. 校验并扣除经验
            if (user.Stats.Experience < cost)
            {
                return BadRequest(new { message = $"经验不足，当前 {user.Stats.Experience}，需要 {cost}" });
            }
            user.Stats.Experience -= cost;

            // 4. 创建游戏主记录
            var game = new Models.Game.Game
            {
                Type = dto.Type ?? "questionnaire",
                Icon = dto.Icon ?? "🎮",
                Title = dto.Title,
                Description = dto.Description,
                Status = "草稿",
                CreatorId = userId,
                CreatedAt = DateTime.UtcNow,
                UpdatedAt = DateTime.UtcNow,
                ExpCost = cost,
                PlayCount = 0
            };
            _context.Games.Add(game);
            await _context.SaveChangesAsync();

            // 5. 创建问卷配置
            var questionnaire = new GameQuestionnaire
            {
                GameId = game.Id,
                Scoring = dto.Scoring ?? "sum"
            };
            _context.GameQuestionnaires.Add(questionnaire);
            await _context.SaveChangesAsync();

            // 6. 创建题目、选项、结果
            int order = 0;
            foreach (var qDto in dto.Questions)
            {
                var question = new GameQuestion
                {
                    QuestionnaireId = questionnaire.Id,
                    Type = qDto.Type ?? "single",
                    Text = qDto.Text,
                    Image = qDto.Image ?? "",
                    Order = order++
                };
                _context.GameQuestions.Add(question);
                await _context.SaveChangesAsync();

                int optOrder = 0;
                foreach (var optDto in qDto.Options)
                {
                    var option = new GameOption
                    {
                        QuestionId = question.Id,
                        Label = optDto.Label,
                        Value = optDto.Value,
                        Image = optDto.Image ?? "",
                        Order = optOrder++
                    };
                    _context.GameOptions.Add(option);
                }
            }

            order = 0;
            foreach (var rDto in dto.Results)
            {
                // 使用 Desc 或 Description
                var descValue = rDto.Desc ?? rDto.Description;
                var result = new GameResult
                {
                    QuestionnaireId = questionnaire.Id,
                    Min = rDto.Min,
                    Max = rDto.Max,
                    Title = rDto.Title,
                    Description = descValue,
                    Icon = rDto.Icon ?? "🏷️",
                    Image = rDto.Image ?? "",
                    Order = order++
                };
                _context.GameResults.Add(result);
            }

            // 7. 记录经验日志
            _context.UserExpLogs.Add(new UserExpLog
            {
                UserId = userId,
                Change = -cost,
                Reason = $"创建游戏：{dto.Title}",
                CreatedAt = DateTime.UtcNow
            });

            // 8. 保存所有更改
            await _context.SaveChangesAsync();

            // 9. 加载完整数据
            var created = await _context.Games
                .Include(g => g.Creator)
                .Include(g => g.Questionnaire)
                    .ThenInclude(q => q.Questions)
                        .ThenInclude(q => q.Options)
                .Include(g => g.Questionnaire)
                    .ThenInclude(q => q.Results)
                .FirstOrDefaultAsync(g => g.Id == game.Id);

            // 10. 映射为 DTO 返回
            var response = MapToResponseDto(created, user.Username);

            return CreatedAtAction(nameof(GetGame), new { id = game.Id }, response);
        }

        // ==================== 获取单个游戏详情 ====================
        [HttpGet("{id}")]
        public async Task<IActionResult> GetGame(int id)
        {
            var game = await _context.Games
                .Include(g => g.Creator)
                .Include(g => g.Questionnaire)
                    .ThenInclude(q => q.Questions)
                        .ThenInclude(q => q.Options)
                .Include(g => g.Questionnaire)
                    .ThenInclude(q => q.Results)
                .FirstOrDefaultAsync(g => g.Id == id);

            if (game == null)
                return NotFound();

            var response = MapToResponseDto(game, game.Creator?.Username ?? "未知用户");
            return Ok(response);
        }

        // ==================== 获取游戏列表（支持分页和筛选） ====================
        [HttpGet]
        public async Task<IActionResult> GetGames(
            [FromQuery] string? type = null,
            [FromQuery] string? status = null,
            [FromQuery] int page = 1,
            [FromQuery] int pageSize = 10)
        {
            var query = _context.Games
                .Include(g => g.Creator)
                .Include(g => g.Questionnaire)
                .AsQueryable();

            if (!string.IsNullOrEmpty(type))
                query = query.Where(g => g.Type == type);
            if (!string.IsNullOrEmpty(status))
                query = query.Where(g => g.Status == status);

            var total = await query.CountAsync();
            var items = await query
                .OrderByDescending(g => g.CreatedAt)
                .Skip((page - 1) * pageSize)
                .Take(pageSize)
                .Select(g => new GameListItemDto
                {
                    Id = g.Id,
                    Type = g.Type,
                    Icon = g.Icon,
                    Title = g.Title,
                    Description = g.Description,
                    Status = g.Status,
                    CreatedAt = g.CreatedAt,
                    UpdatedAt = g.UpdatedAt,
                    ExpCost = g.ExpCost,
                    PlayCount = g.PlayCount,
                    CreatorName = g.Creator != null ? g.Creator.Username : "未知用户",
                    QuestionnaireId = g.Questionnaire != null ? g.Questionnaire.Id : (int?)null
                })
                .ToListAsync();

            return Ok(new { total, items });
        }

        // ==================== 获取当前用户创建的游戏 ====================
        [HttpGet("my")]
        public async Task<IActionResult> GetMyGames(
            [FromQuery] string? status = null,
            [FromQuery] int page = 1,
            [FromQuery] int pageSize = 10)
        {
            var userId = Guid.Parse(User.FindFirst(ClaimTypes.NameIdentifier).Value);

            var query = _context.Games
                .Where(g => g.CreatorId == userId)
                .Include(g => g.Creator)
                .Include(g => g.Questionnaire)
                .AsQueryable();

            if (!string.IsNullOrEmpty(status))
                query = query.Where(g => g.Status == status);

            var total = await query.CountAsync();
            var items = await query
                .OrderByDescending(g => g.CreatedAt)
                .Skip((page - 1) * pageSize)
                .Take(pageSize)
                .Select(g => new GameListItemDto
                {
                    Id = g.Id,
                    Type = g.Type,
                    Icon = g.Icon,
                    Title = g.Title,
                    Description = g.Description,
                    Status = g.Status,
                    CreatedAt = g.CreatedAt,
                    UpdatedAt = g.UpdatedAt,
                    ExpCost = g.ExpCost,
                    PlayCount = g.PlayCount,
                    CreatorName = g.Creator != null ? g.Creator.Username : "未知用户",
                    QuestionnaireId = g.Questionnaire != null ? g.Questionnaire.Id : (int?)null
                })
                .ToListAsync();

            return Ok(new { total, items });
        }

        // ==================== 更新游戏（修改元数据或内容） ====================
        [HttpPut("{id}")]
        public async Task<IActionResult> UpdateGame(int id, [FromBody] UpdateGameDto dto)
        {
            var userId = Guid.Parse(User.FindFirst(ClaimTypes.NameIdentifier).Value);

            var game = await _context.Games
                .Include(g => g.Creator)
                .Include(g => g.Questionnaire)
                    .ThenInclude(q => q.Questions)
                        .ThenInclude(q => q.Options)
                .Include(g => g.Questionnaire)
                    .ThenInclude(q => q.Results)
                .FirstOrDefaultAsync(g => g.Id == id);

            if (game == null)
                return NotFound();

            if (game.CreatorId != userId)
                return Forbid();

            // 更新元数据
            game.Title = dto.Title ?? game.Title;
            game.Description = dto.Description ?? game.Description;
            game.Icon = dto.Icon ?? game.Icon;
            game.Status = dto.Status ?? game.Status;
            game.UpdatedAt = DateTime.UtcNow;

            if (game.Questionnaire != null && !string.IsNullOrEmpty(dto.Scoring))
                game.Questionnaire.Scoring = dto.Scoring;

            await _context.SaveChangesAsync();

            var response = MapToResponseDto(game, game.Creator?.Username ?? "未知用户");
            return Ok(response);
        }

        // ==================== 删除游戏 ====================
        [HttpDelete("{id}")]
        public async Task<IActionResult> DeleteGame(int id)
        {
            var userId = Guid.Parse(User.FindFirst(ClaimTypes.NameIdentifier).Value);

            var game = await _context.Games
                .Include(g => g.Questionnaire)
                .FirstOrDefaultAsync(g => g.Id == id);

            if (game == null)
                return NotFound();

            if (game.CreatorId != userId)
                return Forbid();

            _context.Games.Remove(game);
            await _context.SaveChangesAsync();
            return NoContent();
        }

        // ==================== 私有辅助方法 ====================
        private GameResponseDto MapToResponseDto(Models.Game.Game game, string creatorName)
        {
            return new GameResponseDto
            {
                Id = game.Id,
                Type = game.Type,
                Icon = game.Icon,
                Title = game.Title,
                Description = game.Description,
                Status = game.Status,
                CreatorId = game.CreatorId,
                CreatorName = creatorName,
                CreatedAt = game.CreatedAt,
                UpdatedAt = game.UpdatedAt,
                ExpCost = game.ExpCost,
                PlayCount = game.PlayCount,
                Questionnaire = game.Questionnaire == null ? null : new GameQuestionnaireDto
                {
                    Id = game.Questionnaire.Id,
                    Scoring = game.Questionnaire.Scoring,
                    Questions = game.Questionnaire.Questions?
                        .OrderBy(q => q.Order)
                        .Select(q => new GameQuestionDto
                        {
                            Id = q.Id,
                            Type = q.Type,
                            Text = q.Text,
                            Image = q.Image,
                            Order = q.Order,
                            Options = q.Options?
                                .OrderBy(o => o.Order)
                                .Select(o => new GameOptionDto
                                {
                                    Id = o.Id,
                                    Label = o.Label,
                                    Value = o.Value,
                                    Image = o.Image,
                                    Order = o.Order
                                }).ToList() ?? new List<GameOptionDto>()
                        }).ToList() ?? new List<GameQuestionDto>(),
                    Results = game.Questionnaire.Results?
                        .OrderBy(r => r.Order)
                        .Select(r => new GameResultDto
                        {
                            Id = r.Id,
                            Min = r.Min,
                            Max = r.Max,
                            Title = r.Title,
                            Description = r.Description,
                            Icon = r.Icon,
                            Image = r.Image,
                            Order = r.Order
                        }).ToList() ?? new List<GameResultDto>()
                }
            };
        }
    }
}

Controllers/Admin/AdminUserController.cs:
﻿using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using TaiChuWeb_V2.DbContext; // 你的实际 DbContext
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using TaiChuWeb_V2.Dtos.Admin.AdminUser; // 引入独立的 DTO 命名空间
using TaiChuWeb_V2.Models.User;

namespace TaiChuWeb_V2.Controllers.Admin
{
    [ApiController]
    [Route("api/admin/users")]
    // [Authorize] 
    // 💡 建议加上自定义的策略或角色拦截，例如：[Authorize(Roles = "SuperAdmin,User_Audit")]
    public class AdminUserController : ControllerBase
    {
        private readonly AppDbContext _context;

        public AdminUserController(AppDbContext context)
        {
            _context = context;
        }

        // ==========================================
        // 1. 获取用户详情 (支持分页与联合过滤)
        // GET: api/admin/users?page=1&pageSize=30&search=...&permission=...&reputation=...
        // ==========================================
        [HttpGet]
        public async Task<IActionResult> GetUsers(
            [FromQuery] int page = 1,
            [FromQuery] int pageSize = 30,
            [FromQuery] string? search = null,
            [FromQuery] string? permission = null,
            [FromQuery] string? reputation = null)
        {
            var query = _context.Users
                .Include(u => u.Profile)
                .Include(u => u.Stats)
                .AsNoTracking()
                .AsQueryable();

            // 1. 关键字模糊查询 (匹配 GUID、用户名、邮箱)
            if (!string.IsNullOrWhiteSpace(search))
            {
                var searchLower = search.ToLower();
                query = query.Where(u =>
                    u.Username.ToLower().Contains(searchLower) ||
                    (u.Email != null && u.Email.ToLower().Contains(searchLower)) ||
                    u.Id.ToString() == search);
            }

            // 2. 权限过滤
            if (!string.IsNullOrWhiteSpace(permission) && Enum.TryParse<AdminPermission>(permission, out var permEnum))
            {
                var userIdsWithPerm = _context.UserPermissions
                    .Where(p => p.Permission == permEnum)
                    .Select(p => p.UserId);

                query = query.Where(u => userIdsWithPerm.Contains(u.Id));
            }

            // 3. 信誉分过滤
            if (reputation == "low")
            {
                query = query.Where(u => u.Stats != null && u.Stats.Reputation < 90);
            }
            else if (reputation == "normal")
            {
                // 默认信誉为100，所以 Stats 为 null 的新用户也算 normal
                query = query.Where(u => u.Stats == null || u.Stats.Reputation >= 90);
            }

            // 计算匹配条件的总人数
            var totalCount = await query.CountAsync();

            // 分页拉取数据
            var users = await query
                .OrderByDescending(u => u.CreatedAt)
                .Skip((page - 1) * pageSize)
                .Take(pageSize)
                .ToListAsync();

            // 为了避免 N+1 查询问题，一次性查出这批用户的系统权限
            var userIds = users.Select(u => u.Id).ToList();
            var permissions = await _context.UserPermissions
                .Where(p => userIds.Contains(p.UserId))
                .AsNoTracking()
                .ToListAsync();

            var permLookup = permissions
                .GroupBy(p => p.UserId)
                .ToDictionary(g => g.Key, g => g.Select(p => p.Permission.ToString()).ToList());

            // 映射为前端需要的 DTO
            var items = users.Select(u => new AdminUserDto
            {
                Id = u.Id.ToString(),
                Username = u.Username,
                Email = u.Email,
                CreatedAt = u.CreatedAt,
                Permissions = permLookup.ContainsKey(u.Id) ? permLookup[u.Id] : new List<string>(),

                Profile = u.Profile == null ? null : new AdminUserProfileDto
                {
                    Avatar = u.Profile.Avatar,
                    Gender = u.Profile.Gender,
                    Bio = u.Profile.Bio,
                    Mood = u.Profile.Mood,
                    Birthday = u.Profile.Birthday?.ToString("yyyy-MM-dd"),
                    PhoneNumber = u.Profile.PhoneNumber,
                    Age = u.Profile.Age,
                    Zodiac = u.Profile.Zodiac,
                    ChineseZodiac = u.Profile.ChineseZodiac
                },

                Stats = u.Stats == null ? null : new AdminUserStatsDto
                {
                    Level = u.Stats.Level,
                    Experience = u.Stats.Experience,
                    Reputation = u.Stats.Reputation,
                    Title = u.Stats.Title,
                    CurrentSignStreak = u.Stats.CurrentSignStreak,
                    MaxSignStreak = u.Stats.MaxSignStreak,
                    UsedNotes = u.Stats.UsedNotes,
                    UsedSpaces = u.Stats.UsedSpaces,
                    MaxNotes = u.Stats.MaxNotes,
                    MaxSpaces = u.Stats.MaxSpaces,
                    MaxProjectCount = u.Stats.MaxProjectCount
                }
            }).ToList();

            // 返回标准的带有分页元数据的匿名对象
            return Ok(new
            {
                TotalCount = totalCount,
                Page = page,
                PageSize = pageSize,
                Items = items
            });
        }

        // ==========================================
        // 2. 深度更新用户核心资产与配额 (Stats)
        // PUT: api/admin/users/{userId}/stats
        // ==========================================
        [HttpPut("{userId:guid}/stats")]
        public async Task<IActionResult> UpdateStats(Guid userId, [FromBody] UpdateStatsPayload payload)
        {
            var stats = await _context.UserStats.FirstOrDefaultAsync(s => s.UserId == userId);

            if (stats == null)
            {
                // 如果用户还没有 Stats 数据，则为他初始化一条
                stats = new UserStats { UserId = userId };
                _context.UserStats.Add(stats);
            }

            stats.Reputation = payload.Reputation;
            stats.Experience = payload.Experience;
            stats.MaxSpaces = payload.MaxSpaces;
            stats.MaxNotes = payload.MaxNotes;
            stats.MaxProjectCount = payload.MaxProjectCount;

            await _context.SaveChangesAsync();
            return Ok(new { message = "用户核心资产与配额已更新" });
        }

        // ==========================================
        // 3. 指派用户系统级管理权限 (UserPermission)
        // PUT: api/admin/users/{userId}/permissions
        // ==========================================
        [HttpPut("{userId:guid}/permissions")]
        public async Task<IActionResult> UpdatePermissions(Guid userId, [FromBody] List<string> newPermissions)
        {
            var userExists = await _context.Users.AnyAsync(u => u.Id == userId);
            if (!userExists) return NotFound(new { message = "系统未找到该用户凭证" });

            // 1. 删除旧的所有权限
            var existingPerms = await _context.UserPermissions.Where(p => p.UserId == userId).ToListAsync();
            _context.UserPermissions.RemoveRange(existingPerms);

            // 2. 注入新权限
            foreach (var permStr in newPermissions)
            {
                if (Enum.TryParse<AdminPermission>(permStr, out var permEnum))
                {
                    _context.UserPermissions.Add(new UserPermission
                    {
                        UserId = userId,
                        Permission = permEnum
                    });
                }
            }

            await _context.SaveChangesAsync();
            return Ok(new { message = "用户权限指派已生效" });
        }

        // ==========================================
        // 4. 快捷审计干预：违规扣除信誉分
        // POST: api/admin/users/{userId}/punish
        // ==========================================
        [HttpPost("{userId:guid}/punish")]
        public async Task<IActionResult> Punish(Guid userId, [FromBody] PunishPayload payload)
        {
            var stats = await _context.UserStats.FirstOrDefaultAsync(s => s.UserId == userId);
            if (stats == null) return NotFound(new { message = "该用户未激活资产账单，无法扣除" });

            if (payload.Deduction <= 0) return BadRequest(new { message = "扣除分数必须大于0" });

            // 扣除信誉分，最低限制为 0
            stats.Reputation = Math.Max(0, stats.Reputation - payload.Deduction);

            await _context.SaveChangesAsync();
            return Ok(new { message = $"已成功扣除 {payload.Deduction} 点信誉分" });
        }
    }
}

