app.UseRouting();          // 2. 路由
app.UseCors("AllowAll");   // 3. CORS 必须放在 UseRouting 和 UseAuthentication 之间
app.UseAuthentication();   // 4. 认证
app.UseAuthorization();    // 5. 授权

app.MapControllers();
app.MapHub<GameHub>("/signalr/game");

app.Run();

